import{getContext as e,getElement as t,store as s}from"@wordpress/interactivity";let n=0;const{state:r}=s("auclair",{state:{searchQuery:"",suggestions:[],get hasSuggestions(){return this.suggestions.length>0}},actions:{*setSearchQuery(){const s=e(),{ref:i}=t(),o=i.value;if(r.searchQuery=o,!s.liveSuggest||o.trim().length<2)return void(r.suggestions=[]);const a=++n,c=yield window.fetch(`/wp-json/wp/v2/kb_article?search=${encodeURIComponent(o)}&per_page=5&_fields=id,title,link`);if(a!==n||!c.ok)return;const l=yield c.json();r.suggestions=l.map(e=>({id:e.id,title:e.title.rendered,url:e.link}))},handleSearchKeydown(t){if("Enter"!==t.key)return;const s=e();window.location.href=s.action.replace("%s",encodeURIComponent(r.searchQuery))}}});